import React, { useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";

export default function Lobby() {
  const [searchParams] = useSearchParams();
  const room = searchParams.get("room");
  const navigate = useNavigate();

  useEffect(() => {
    if (!room) {
      alert("No room provided — redirecting to join page.");
      navigate("/join");
    }
  }, [room, navigate]);

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg, #0f0f10 0%, #1a1a1d 100%)",
        padding: "40px",
        fontFamily: "Inter, sans-serif",
        display: "flex",
        justifyContent: "center",
        alignItems: "flex-start",
        color: "#fff",
      }}
    >
      <div
        style={{
          width: "900px",
          background: "rgba(255,255,255,0.05)",
          padding: "40px",
          borderRadius: "18px",
          backdropFilter: "blur(16px)",
          boxShadow: "0 10px 40px rgba(0,0,0,0.4)",
          border: "1px solid rgba(255,255,255,0.08)",
        }}
      >
        {/* HEADER */}
        <h1 style={{ fontSize: "34px", marginBottom: "10px", fontWeight: 700 }}>
          Room Lobby
        </h1>
        <h2
          style={{
            fontSize: "22px",
            marginBottom: "25px",
            opacity: 0.9,
            letterSpacing: "1px",
          }}
        >
          Room Code: <span style={{ color: "#4facfe" }}>{room}</span>
        </h2>

        {/* DESCRIPTION */}
        <p
          style={{
            fontSize: "15px",
            color: "#c9c9c9",
            marginBottom: "35px",
            lineHeight: "1.6",
          }}
        >
          Select how you want to collaborate in this room.  
          You can switch between modes anytime.
        </p>

        {/* BUTTON GRID */}
        <div
          style={{
            display: "grid",
            gap: "25px",
            gridTemplateColumns: "1fr 1fr",
          }}
        >
          {/* EXPLAINER CARD */}
          <div
            style={{
              background: "rgba(255,255,255,0.07)",
              padding: "25px",
              borderRadius: "14px",
              border: "1px solid rgba(255,255,255,0.1)",
            }}
          >
            <h3 style={{ marginBottom: "10px", fontSize: "20px" }}>
              🔍 Code Explainer
            </h3>
            <p style={{ color: "#b5b5b5", marginBottom: "18px" }}>
              Get AI explanations, flow analysis, insights & output prediction.
            </p>

            <button
              onClick={() => navigate(`/explainer?room=${room}`)}
              style={{
                width: "100%",
                padding: "12px",
                background:
                  "linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)",
                border: "none",
                borderRadius: "10px",
                color: "#000",
                fontSize: "16px",
                fontWeight: 600,
                cursor: "pointer",
              }}
            >
              Open Code Explainer
            </button>
          </div>

          {/* COLLABORATION CARD */}
          <div
            style={{
              background: "rgba(255,255,255,0.07)",
              padding: "25px",
              borderRadius: "14px",
              border: "1px solid rgba(255,255,255,0.1)",
            }}
          >
            <h3 style={{ marginBottom: "10px", fontSize: "20px" }}>
              👥 Live Collaboration
            </h3>
            <p style={{ color: "#b5b5b5", marginBottom: "18px" }}>
              Real-time editor sharing, comments & synced updates.
            </p>

            <button
              onClick={() => navigate(`/collaboration?room=${room}`)}
              style={{
                width: "100%",
                padding: "12px",
                background:
                  "linear-gradient(135deg, #667db6 0%, #0082c8 100%)",
                border: "none",
                borderRadius: "10px",
                color: "#fff",
                fontSize: "16px",
                fontWeight: 600,
                cursor: "pointer",
              }}
            >
              Open Collaboration Mode
            </button>
          </div>
        </div>

        {/* BACK BUTTON */}
        <div style={{ marginTop: "40px", textAlign: "center" }}>
          <button
            onClick={() => navigate("/join")}
            style={{
              padding: "12px 20px",
              background: "rgba(255,255,255,0.1)",
              color: "#fff",
              border: "1px solid rgba(255,255,255,0.2)",
              borderRadius: "10px",
              cursor: "pointer",
              fontSize: "15px",
            }}
          >
            ⬅ Back to Join Page
          </button>
        </div>
      </div>
    </div>
  );
}
